// Typed C++ context makes these malformed mapping shapes unrepresentable: caller_context_extra_key, caller_context_missing_null_allowed, caller_context_missing_profile_handle, caller_context_null_allowed_nonboolean.

void TestAllOwnedMutationFixtures(const std::shared_ptr<const dt::DateValidatedProfileHandleV1>& p){
  auto invalid=*p;invalid.profile_material[16]^=1;
  for(const auto& m:k_cover_mutations){auto b=Hex(m.hex);auto r=dt::DecodeDateCoveringValueNoAllocV1(m.invalid_profile?invalid:*p,m.null_allowed,b);Require(!r.ok()&&r.diagnostic.diagnostic_code==m.code,m.id);}
  for(const auto& m:k_range_mutations){auto b=Hex(m.hex);auto r=dt::DecodeDateRangePairNoAllocV1(*p,b);Require(!r.ok()&&r.diagnostic.diagnostic_code==m.code,m.id);}
  for(const auto& m:k_zone_mutations){auto b=Hex(m.hex);auto r=dt::DecodeDateZoneMapNoAllocV1(m.invalid_profile?invalid:*p,b);Require(!r.ok()&&r.diagnostic.diagnostic_code==m.code,m.id);}
  for(const auto& m:k_statistics_mutations){auto b=Hex(m.hex);auto r=dt::DecodeDateStatisticsProjectionV1(p,b);Require(!r.ok()&&r.diagnostic.diagnostic_code==m.code,m.id);}
  for(const auto& m:k_backup_mutations){auto b=Hex(m.hex);auto r=dt::DecodeDateBackupTupleNoAllocV1(*p,m.null_allowed,b);Require(!r.ok()&&r.diagnostic.diagnostic_code==m.code,m.id);}
}

