  for(auto literal:{k_statistics_vectors_empty,k_statistics_vectors_null_only_population,k_statistics_vectors_minimum_maximum,k_statistics_vectors_correlation_unavailable,k_statistics_vectors_maximum_record_counts}){auto bytes=Hex(literal);auto d=dt::DecodeDateStatisticsProjectionV1(p,bytes);Require(d.ok(),"exact statistics decode");auto& s=d.statistics;dt::DateStatisticsProjectionV1 q;q.profile=p;q.provider_evidence=std::make_shared<const dt::DateStatisticsProviderEvidenceHandleV1>(dt::DateStatisticsProviderEvidenceHandleV1{s.provider_evidence_uuid});q.statistics_uuid=s.statistics_uuid;q.source_object_uuid=s.source_object_uuid;q.schema_epoch=s.schema_epoch;q.collection_epoch=s.collection_epoch;q.security_epoch=s.security_epoch;q.row_count=s.row_count;q.null_count=s.null_count;q.value_count=s.value_count;q.minimum_maximum_present=s.minimum_maximum_present;q.minimum_day=s.minimum_day;q.maximum_day=s.maximum_day;q.histogram=s.histogram;q.mcv=s.mcv;auto e=dt::EncodeDateStatisticsProjectionV1(q);Require(e.ok()&&e.bytes==bytes,"exact statistics reencode");}
