void TestIndexFacts(const std::shared_ptr<const dt::DateValidatedProfileHandleV1>& p){
  std::set<std::array<platform::byte,16>> ids;unsigned admitted=0,conditional=0,na=0;
  using D=dt::DateIndexDispositionV1;using K=dt::DateProjectionKindV1;
  const std::array<D,16> dispositions{{D::not_applicable,D::admitted_with_recheck,D::admitted_with_recheck,D::admitted_exact_if_budget,D::admitted_with_recheck,D::admitted_payload_only,D::not_applicable,D::conditional,D::not_applicable,D::not_applicable,D::admitted_with_recheck,D::conditional,D::admitted_exact_if_budget,D::not_applicable,D::admitted_exact_selected_mode,D::not_applicable}};
  const std::array<K,16> projections{{K::none,K::equality_hash,K::zone_map,K::sort_key,K::zone_map,K::covering_value,K::none,K::conditional_result,K::none,K::none,K::equality_hash,K::conditional_underlying,K::range_pair,K::none,K::none,K::none}};
  const std::array<bool,16> rechecks{{false,true,true,false,true,false,false,true,false,false,true,true,false,false,false,false}};
  const std::array<bool,16> owner_handoffs{{true,false,false,false,false,false,true,true,true,true,false,true,false,true,false,true}};
  for(unsigned i=0;i<16;++i){auto r=dt::ResolveDateIndexFamilyV1(static_cast<dt::DateIndexFamilyV1>(i));Require(r.compatibility_generation==1&&r.compatibility_uuid==ExpectedIndexUuid(i+1)&&r.disposition==dispositions[i]&&r.projection==projections[i]&&r.exact_recheck_required==rechecks[i]&&r.receiving_owner_resolution_required==owner_handoffs[i],"exact index registry row");Require(ids.insert(r.compatibility_uuid.bytes).second,"index UUID unique");if(r.disposition==dt::DateIndexDispositionV1::conditional)++conditional;else if(r.disposition==dt::DateIndexDispositionV1::not_applicable)++na;else ++admitted;}
  Require(admitted==8&&conditional==2&&na==6,"index partition");
  auto invalid=dt::ResolveDateIndexFamilyV1(static_cast<dt::DateIndexFamilyV1>(255));Require(invalid.compatibility_uuid.is_nil()&&invalid.compatibility_generation==0&&invalid.disposition==dt::DateIndexDispositionV1::not_applicable,"invalid family bounded");
  auto v=Value(p,-1);dt::DateIndexProjectionRequestV1 q;q.value=&v;
  auto invalid_profile=*p;invalid_profile.profile_material[0]^=1;Require(!dt::ValidateDateProfileHandleV1(invalid_profile).ok(),"mutated profile invalid");auto invalid_profile_value=dt::DateOwnedValueV1{std::make_shared<const dt::DateValidatedProfileHandleV1>(invalid_profile),dt::DateValueStateV1::value,0};q.value=&invalid_profile_value;q.family=static_cast<dt::DateIndexFamilyV1>(255);auto precedence=dt::ProjectDateIndexValueV1(q);Require(precedence.diagnostic.diagnostic_code=="CTI.TEMPORAL.DESCRIPTOR_INVALID","profile before family");q.value=&v;
  q.family=dt::DateIndexFamilyV1::bitmap;q.mode=dt::DateProjectionModeV1::equality_hash;auto hash=dt::ProjectDateIndexValueV1(q);Require(hash.ok()&&hash.bytes.size()==32&&hash.resolution.exact_recheck_required,"bitmap hash");
  q.provider_max_key_bytes=31;auto short_key=dt::ProjectDateIndexValueV1(q);Require(!short_key.ok()&&short_key.diagnostic.diagnostic_code=="CTI.TEMPORAL.INDEX_KEY_REFUSED","provider refusal");
  auto dirty=v;dirty.state=static_cast<dt::DateValueStateV1>(255);q.value=&dirty;q.mode=dt::DateProjectionModeV1::payload;auto mode_first=dt::ProjectDateIndexValueV1(q);Require(mode_first.diagnostic.diagnostic_code=="CTI.TEMPORAL.INDEX_KEY_REFUSED","mode before state");q.value=&v;q.mode=dt::DateProjectionModeV1::equality_hash;
  q.provider_max_key_bytes=~platform::u64{0};q.family=dt::DateIndexFamilyV1::document_path;q.mode=dt::DateProjectionModeV1::unspecified;auto owner=dt::ProjectDateIndexValueV1(q);Require(!owner.ok()&&owner.owner_fact_only&&owner.diagnostic.diagnostic_code.empty(),"owner fact no optimizer diagnostic");
  q.family=dt::DateIndexFamilyV1::expression;q.selected_conditional_family=nullptr;Require(dt::ProjectDateIndexValueV1(q).owner_fact_only,"conditional unresolved");
  auto selected=dt::ResolveDateIndexFamilyV1(dt::DateIndexFamilyV1::btree);q.selected_conditional_family=&selected;q.mode=dt::DateProjectionModeV1::ascending_nulls_last;Require(dt::ProjectDateIndexValueV1(q).ok(),"conditional exact selection");selected.compatibility_generation=2;Require(dt::ProjectDateIndexValueV1(q).owner_fact_only,"conditional mutation refused");
  using O=dt::DateIndexPredicateOperationV1;using P=dt::DateIndexPredicateFactV1;
  Require(dt::ResolveDateIndexPredicateV1(dt::DateIndexFamilyV1::bitmap,O::is_null).fact==P::requires_exact_state_day_recheck_never_final_match,"bitmap predicate fact");
  Require(dt::ResolveDateIndexPredicateV1(dt::DateIndexFamilyV1::brin_like,O::range).fact==P::prune_only_mandatory_source_row_predicate_recheck_never_final_match,"zone predicate fact");
  Require(dt::ResolveDateIndexPredicateV1(dt::DateIndexFamilyV1::btree,O::order).fact==P::exact_no_recheck_after_decode_reencode,"btree predicate fact");
  Require(!dt::ResolveDateIndexPredicateV1(dt::DateIndexFamilyV1::hash,O::order).admitted,"unsupported predicate refusal");

  struct Variant{dt::DateIndexFamilyV1 family;dt::DateProjectionModeV1 mode;bool sql_null;bool zone;bool zone_values;platform::u64 extent;};
  using F=dt::DateIndexFamilyV1;using M=dt::DateProjectionModeV1;
  const std::array<Variant,29> variants{{
    {F::bitmap,M::equality_hash,true,false,false,32},{F::bitmap,M::equality_hash,false,false,false,32},
    {F::brin_like,M::zone_map,false,true,false,96},{F::brin_like,M::zone_map,false,true,true,304},
    {F::columnar_zone_map,M::zone_map,false,true,false,96},{F::columnar_zone_map,M::zone_map,false,true,true,304},
    {F::btree,M::ascending_nulls_first,true,false,false,100},{F::btree,M::ascending_nulls_first,false,false,false,104},
    {F::btree,M::ascending_nulls_last,true,false,false,100},{F::btree,M::ascending_nulls_last,false,false,false,104},
    {F::btree,M::descending_nulls_first,true,false,false,100},{F::btree,M::descending_nulls_first,false,false,false,104},
    {F::btree,M::descending_nulls_last,true,false,false,100},{F::btree,M::descending_nulls_last,false,false,false,104},
    {F::covering_included,M::payload,true,false,false,1},{F::covering_included,M::payload,false,false,false,5},
    {F::hash,M::equality_hash,true,false,false,32},{F::hash,M::equality_hash,false,false,false,32},
    {F::range_exclusion,M::ascending_nulls_last_pair,false,false,false,208},
    {F::temporary_work,M::equality_hash,true,false,false,32},{F::temporary_work,M::equality_hash,false,false,false,32},
    {F::temporary_work,M::ascending_nulls_first,true,false,false,100},{F::temporary_work,M::ascending_nulls_first,false,false,false,104},
    {F::temporary_work,M::ascending_nulls_last,true,false,false,100},{F::temporary_work,M::ascending_nulls_last,false,false,false,104},
    {F::temporary_work,M::descending_nulls_first,true,false,false,100},{F::temporary_work,M::descending_nulls_first,false,false,false,104},
    {F::temporary_work,M::descending_nulls_last,true,false,false,100},{F::temporary_work,M::descending_nulls_last,false,false,false,104}}};
  auto present=Value(p,-1),upper=Value(p,2);dt::DateOwnedValueV1 sql_null{p,dt::DateValueStateV1::sql_null,0};dt::DateZoneMapRequestV1 empty_zone{p,nullptr,nullptr,2,0};dt::DateZoneMapRequestV1 value_zone{p,&present,&upper,2,3};
  for(const auto& x:variants){dt::DateIndexProjectionRequestV1 request;request.family=x.family;request.mode=x.mode;request.value=x.sql_null?&sql_null:&present;request.upper_value=&upper;request.zone_map=x.zone?(x.zone_values?&value_zone:&empty_zone):nullptr;request.provider_max_key_bytes=x.extent;auto projected=dt::ProjectDateIndexValueV1(request);Require(projected.ok()&&projected.bytes.size()==x.extent,"exact index selection variant");request.provider_max_key_bytes=x.extent-1;auto refused=dt::ProjectDateIndexValueV1(request);Require(!refused.ok()&&refused.bytes.empty()&&refused.diagnostic.diagnostic_code=="CTI.TEMPORAL.INDEX_KEY_REFUSED","exact provider one-short");}
}

