  auto invalid_profile=*p;invalid_profile.profile_material[0]^=1;auto combined=dt::DecodeDateCoveringValueNoAllocV1(invalid_profile,true,bad);Require(!combined.ok()&&combined.diagnostic.diagnostic_code=="CTI.TEMPORAL.DESCRIPTOR_INVALID","cover profile precedence");
